class Solution:
    def minimizeResult(self, expression: str) -> str:
        p = expression.index('+')
        a, b = expression[:p], expression[p+1:]
        best, ans = None, ''
        for i in range(len(a) + 1):
            for j in range(len(b) + 1):
                left = int(a[:i]) if i > 0 else 1
                right = int(b[j:]) if j < len(b) else 1
                val = left * (int(a[i:]) + int(b[:j])) * right
                if best is None or val < best:
                    best = val
                    ans = a[:i] + '(' + a[i:] + '+' + b[:j] + ')' + b[j:]
        return ans

