    string minimizeResult(string e) {
        int p = e.find('+');
        string a = e.substr(0, p), b = e.substr(p + 1);
        long long best = LLONG_MAX; string ans;
        for (int i = 0; i <= a.size(); i++)
            for (int j = 0; j <= b.size(); j++) {
                long long L = i ? stoll(a.substr(0, i)) : 1;
                long long R = j < b.size() ? stoll(b.substr(j)) : 1;
                long long v = L * (stoll(a.substr(i)) + stoll(b.substr(0, j))) * R;
