class Solution {
    public String minimizeResult(String e) {
        int p = e.indexOf('+');
        String a = e.substring(0, p), b = e.substring(p + 1);
        long best = Long.MAX_VALUE; String ans = "";
        for (int i = 0; i <= a.length(); i++)
            for (int j = 0; j <= b.length(); j++) {
                long L = i > 0 ? Long.parseLong(a.substring(0, i)) : 1;
                long R = j < b.length() ? Long.parseLong(b.substring(j)) : 1;
                long v = L * (Long.parseLong(a.substring(i)) + Long.parseLong(b.substring(0, j))) * R;
                if (v < best) { best = v; ans = a.substring(0, i) + "(" + a.substring(i) + "+" + b.substring(0, j) + ")" + b.substring(j); }
            }
        return ans;
    }
}

