var minimizeResult = function(e) {
    const p = e.indexOf('+'), a = e.slice(0, p), b = e.slice(p + 1);
    let best = Infinity, ans = '';
    for (let i = 0; i <= a.length; i++)
        for (let j = 0; j <= b.length; j++) {
            const L = i ? Number(a.slice(0, i)) : 1;
            const R = j < b.length ? Number(b.slice(j)) : 1;
            const v = L * (Number(a.slice(i)) + Number(b.slice(0, j))) * R;
            if (v < best) { best = v; ans = a.slice(0, i) + '(' + a.slice(i) + '+' + b.slice(0, j) + ')' + b.slice(j); }
        }
    return ans;
};
